/* @generated by stategate from posture.yaml. Do not edit: change the model and run `stategate gen`. */
/* The trace format stategate-view replays. Write the header once, then one
 * record per transition (the HAL's trace hook gives you from, event and to),
 * over any transport: a file, UART, BLE. The viewer refuses a log whose model
 * hash is not the model it has open. */
#ifndef POSTURE_TRACE_H
#define POSTURE_TRACE_H

#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* sha-256 of posture.yaml, the model this code was generated from. */
static const uint8_t posture_model_hash[32] = {0xf1, 0xf3, 0x98, 0xf7, 0xd3, 0x37, 0x3f, 0xf2, 0x99, 0x15, 0x48, 0x74, 0x3e, 0xaf, 0x7f, 0x42, 0x16, 0xcb, 0xbb, 0x56, 0x26, 0x27, 0x56, 0xb2, 0xdb, 0x06, 0x25, 0x2a, 0x05, 0x81, 0x84, 0x21};

/* Appends one machine's entry to a header: id length, id, model hash. */
static inline size_t posture_trace_header_entry(uint8_t *out) {
    size_t n = strlen("posture");
    out[0] = (uint8_t)n;
    memcpy(out + 1, "posture", n);
    memcpy(out + 1 + n, posture_model_hash, 32);
    return 1 + n + 32;
}

/* The header of a log from this machine alone. out needs 45 bytes. */
static inline size_t posture_trace_header(uint8_t *out) {
    memcpy(out, "SGT1", 4);
    out[4] = 1;
    return 5 + posture_trace_header_entry(out + 5);
}

/* Shared by every machine's trace.h, so a system can include them all. */
#ifndef SG_TRACE_RECORD_SIZE
#define SG_TRACE_RECORD_SIZE 11

static inline void sg_trace_record(uint8_t out[SG_TRACE_RECORD_SIZE], uint32_t t_ms, uint16_t seq, uint8_t machine,
                                   uint8_t instance, uint8_t from, uint8_t event, uint8_t to) {
    out[0] = (uint8_t)t_ms;
    out[1] = (uint8_t)(t_ms >> 8);
    out[2] = (uint8_t)(t_ms >> 16);
    out[3] = (uint8_t)(t_ms >> 24);
    out[4] = (uint8_t)seq;
    out[5] = (uint8_t)(seq >> 8);
    out[6] = machine;
    out[7] = instance;
    out[8] = from;
    out[9] = event;
    out[10] = to;
}
#endif

#endif
